#!/usr/bin/env bash
set -euo pipefail

APP_DIR="/opt/betsignal-cloud"
TS=$(date +%F_%H%M%S)
BACKUP_DIR="/root/backups/betsignal/$TS-decision-api-sync"
ARCHIVE="/tmp/apexgol_decision_api_$TS.tgz"
export BACKUP_DIR

mkdir -p "$BACKUP_DIR"
cd "$APP_DIR"

echo "==> ApexGol AI sync: backup reversivel"
python3 - <<'PY'
