    'services/__init__.py',
    'services/footballQuantAiSkill/__init__.py',
    'services/footballQuantAiSkill/agents/football_research_agent.py',
    'services/footballQuantAiSkill/backtesting/backtesting_service.py',
    'services/footballQuantAiSkill/bankroll/bankroll_service.py',
    'services/footballQuantAiSkill/config.py',
    'services/footballQuantAiSkill/continuous_learning/continuous_learning_service.py',
    'services/footballQuantAiSkill/continuous_learning/learning_memory_service.py',
    'services/footballQuantAiSkill/continuous_learning/model_evaluation_service.py',
