    'services/footballQuantAiSkill/data_sources/statsbomb_open_source.py',
    'services/footballQuantAiSkill/data_sources/the_odds_api_source.py',
    'services/footballQuantAiSkill/evaluation/database_discovery_service.py',
    'services/footballQuantAiSkill/historical_data_service.py',
    'services/footballQuantAiSkill/models/hybrid_prediction_service.py',
    'services/footballQuantAiSkill/models/poisson_model_service.py',
    'services/footballQuantAiSkill/normalization/normalizer.py',
    'services/footballQuantAiSkill/rag/rag_knowledge_service.py',
