    'services/footballQuantAiSkill/supabase/research_sync_service.py',
    'services/footballQuantAiSkill/value_betting/value_bet_service.py',
    'services/globalAdaptiveIntelligence/__init__.py',
    'services/globalAdaptiveIntelligence/alerts/alert_service.py',
    'services/globalAdaptiveIntelligence/backtesting/backtesting_engine.py',
    'services/globalAdaptiveIntelligence/config.py',
    'services/globalAdaptiveIntelligence/core.py',
    'services/globalAdaptiveIntelligence/data_sources/registry.py',
    'services/globalAdaptiveIntelligence/ensemble/ensemble_prediction_service.py',
    'services/globalAdaptiveIntelligence/evaluation/anomaly_detection_service.py',
    'services/globalAdaptiveIntelligence/evaluation/drift_detection_service.py',
