    'services/globalAdaptiveIntelligence/meta_learning/meta_learning_service.py',
    'services/globalAdaptiveIntelligence/models/market_efficiency_model.py',
    'services/globalAdaptiveIntelligence/models/mean_reversion_model.py',
    'services/globalAdaptiveIntelligence/models/momentum_model.py',
    'services/globalAdaptiveIntelligence/models/time_series_baseline_model.py',
    'services/globalAdaptiveIntelligence/monte_carlo/monte_carlo_engine.py',
    'services/globalAdaptiveIntelligence/multi_agent/agents.py',
    'services/globalAdaptiveIntelligence/multi_agent/consensus_engine.py',
    'services/globalAdaptiveIntelligence/rag/rag_knowledge_service.py',
    'services/globalAdaptiveIntelligence/reports/report_service.py',
    'services/globalAdaptiveIntelligence/repository.py',
    'services/globalAdaptiveIntelligence/risk/global_risk_service.py',
    'services/globalAdaptiveIntelligence/sports/base.py',
    'services/globalAdaptiveIntelligence/sports/football_adapter.py',
    'services/globalAdaptiveIntelligence/strategy_lab/evolutionary_strategy_engine.py',
    'requirements.txt',
    '.env.example',
    'migrations/2026_05_03_global_adaptive_intelligence.sql',
    'migrations/2026_05_03_global_adaptive_intelligence_rollback.sql',
]
for rel in files:
    src = app / rel
    if src.exists():
        dst = backup / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(src, dst)
print('backup_ok', backup)
