echo "==> sincronizando codigo local validado"
tar -xzf "$ARCHIVE" -C "$APP_DIR"
rm -f "$ARCHIVE"

echo "==> preservando .env da VPS e preparando defaults seguros"
[ -f /opt/.env ] && ln -sf /opt/.env "$APP_DIR/.env"
if [ ! -f "$APP_DIR/.env" ]; then
  cp "$APP_DIR/.env.example" "$APP_DIR/.env"
fi
if ! grep -q '^API_FOOTBALL_BASE_URL=' "$APP_DIR/.env" 2>/dev/null; then
  printf '
API_FOOTBALL_BASE_URL=https://v3.football.api-sports.io
' >> "$APP_DIR/.env"
fi
if ! grep -q '^BRAIN_ENABLED=' "$APP_DIR/.env" 2>/dev/null; then
  printf '
BRAIN_ENABLED=true
' >> "$APP_DIR/.env"
fi
if ! grep -q '^BRAIN_DB_FILE=' "$APP_DIR/.env" 2>/dev/null; then
  printf 'BRAIN_DB_FILE=data/football_brain.db
' >> "$APP_DIR/.env"
fi

